import Foundation
import HegemonCore
import SwiftUI

/// The painted board, traced from Josh's photo: territory outlines, rivers and peaks in the
/// photo's pixel space (generated by tools/board_shapes.py). A generated world carries its own art
/// in the same coordinates (HegemonCore's MapArt).
typealias BoardArt = MapArt

extension MapArt {
    /// The classic board's art.
    static let shared: BoardArt = {
        let url = Bundle.main.url(forResource: "map_shapes", withExtension: "json")!
        let traced = try! JSONDecoder().decode(BoardArt.self, from: Data(contentsOf: url))
        return MapArt(size: traced.size, territories: traced.territories, seas: traced.seas, rivers: traced.rivers,
                      peaks: traced.peaks, seam: 1006)
    }()

    /// How a map is drawn: a generated world's own art, else the painted board.
    static func of(_ map: GameMap) -> BoardArt { map.art ?? shared }

    /// The painted part of the photo (both halves of the board); generated worlds fill the same frame.
    static let frame = CGRect(x: 100, y: 5, width: 1805, height: 915)
}

/// Maps board coordinates into a view, keeping the board's proportions.
struct BoardTransform {
    let scale: CGFloat
    let offset: CGPoint
    /// How much larger to draw lettering and tokens: they grow with the zoom, but more slowly,
    /// so zooming in spreads things out instead of just enlarging them.
    let detail: CGFloat

    /// The whole board fitted to `size`, then zoomed about the view's center and panned.
    init(fitting size: CGSize, zoom: CGFloat = 1, pan: CGSize = .zero) {
        let f = BoardArt.frame
        let fit = min(size.width / f.width, size.height / f.height)
        let fitted = CGPoint(x: (size.width - f.width * fit) / 2 - f.minX * fit,
                             y: (size.height - f.height * fit) / 2 - f.minY * fit)
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        scale = fit * zoom
        offset = CGPoint(x: center.x + (fitted.x - center.x) * zoom + pan.width,
                         y: center.y + (fitted.y - center.y) * zoom + pan.height)
        detail = zoom.squareRoot()
    }

    /// The farthest the board may be panned at a zoom: far enough to reach every edge, no further.
    static func panLimit(_ size: CGSize, zoom: CGFloat) -> CGSize {
        let f = BoardArt.frame
        let fit = min(size.width / f.width, size.height / f.height)
        // Room past every edge, so lands in the board's corners can be brought out from under
        // the status panel, toolbar and buttons to the middle of the screen.
        let zoomed = zoom > 1.01
        return CGSize(width: max(0, (f.width * fit * zoom - size.width) / 2) + size.width * (zoomed ? 0.32 : 0.2),
                      height: max(0, (f.height * fit * zoom - size.height) / 2) + size.height * (zoomed ? 0.36 : 0.25))
    }

    func point(_ p: [Double]) -> CGPoint {
        CGPoint(x: offset.x + CGFloat(p[0]) * scale, y: offset.y + CGFloat(p[1]) * scale)
    }

    func path(_ polygon: [[Double]]) -> Path {
        var path = Path()
        path.addLines(polygon.map(point))
        path.closeSubpath()
        return path
    }
}

/// Colors for civilizations. Rebel factions take a lighter shade of the realm they split from.
enum Palette {
    static let base: [CivilizationID: Color] = [
        "greece": Color(red: 0.20, green: 0.42, blue: 0.85),
        // Royal purple: gold vanished into the painted desert that most of Egypt is.
        "egypt": Color(red: 0.56, green: 0.26, blue: 0.70),
        "italia": Color(red: 0.80, green: 0.20, blue: 0.20),
        "mesopotamia": Color(red: 0.18, green: 0.62, blue: 0.35),
        // Expansion: the Hittites, in saffron.
        "hatti": Color(red: 0.90, green: 0.52, blue: 0.10),
    ]

    /// Each kingdom its own earthy colour, the same every game: ochres, madders, olives, slates.
    static func kingdomColor(_ id: CivilizationID) -> Color {
        let hues: [(Double, Double, Double)] = [
            (0.72, 0.52, 0.22), (0.58, 0.32, 0.22), (0.45, 0.5, 0.25), (0.38, 0.45, 0.52),
            (0.62, 0.42, 0.5), (0.5, 0.38, 0.2), (0.3, 0.5, 0.42), (0.66, 0.6, 0.35),
            (0.55, 0.25, 0.3), (0.42, 0.36, 0.55), (0.7, 0.45, 0.3), (0.35, 0.42, 0.3),
        ]
        let h = id.unicodeScalars.reduce(UInt32(5381)) { ($0 &* 33) &+ $1.value }
        let (r, g, b) = hues[Int(h % UInt32(hues.count))]
        return Color(red: r, green: g, blue: b)
    }

    static func color(_ civ: CivilizationID?, _ state: GameState) -> Color {
        guard let civ else { return Color(white: 0.92) }
        if civ == nativesID { return Color(white: 0.72) }
        if isKingdom(civ) { return kingdomColor(civ) }
        if civ == barbariansID { return Color(red: 0.45, green: 0.30, blue: 0.20) }
        if civ == piratesID { return Color(white: 0.12) }
        if let parent = state.civs[civ]?.rebelledFrom {
            return color(parent, state).opacity(0.45)
        }
        return base[civ] ?? .purple
    }

    static func name(_ civ: CivilizationID, _ state: GameState) -> String {
        if let display = state.civs[civ]?.displayName { return display }
        if civ == nativesID { return "Natives" }
        if let k = state.kingdoms[civ] { return k.name.capitalizedFirst }
        if civ == barbariansID { return "Barbarians" }
        if civ == piratesID { return "Pirates" }
        return civ.prefix(1).uppercased() + civ.dropFirst()
    }
}
